    public IReadOnlyList<HmiScriptCommandDefinition> Commands => _commands;

    public HmiScriptCommandDefinition? FindByKey(string key)
    {
        HmiScriptCommandDefinition? command;
        return _byKey.TryGetValue(key, out command) ? command : null;
    }

    public HmiScriptCommandDefinition? FindByName(string name)
    {
        HmiScriptCommandDefinition? command;
        return _byName.TryGetValue(name, out command) ? command : null;
    }

    public HmiScriptCommand CreateCommandByKey(string key)
    {
        switch (key)
        {
            case @"InternalFunctions.ActivateNextScreen": return new ActivateNextScreenCommand();
            case @"InternalFunctions.ActivatePreviousScreen": return new InternalValueActivatePreviousScreenCommand();
            case @"InternalFunctions.ActivateStartScreen": return new ActivateStartScreenCommand();
            case @"InternalFunctions.ActivateStoredScreen": return new ActivateStoredScreenCommand();
            case @"InternalFunctions.DateToSystemTime": return new DateToSystemTimeCommand();
